const prevData = $('Parse Embedding').first().json;
let ragResults = [];

try {
  // Parse RAG results
  ragResults = Array.isArray($json) ? $json : [];
} catch (e) {
  console.log('RAG parse error:', e.message);
}

// Group examples by acceptance level
const acceptableExamples = ragResults.filter(r => r.acceptance === 'ACCEPTABLE').slice(0, 2);
const passableExamples = ragResults.filter(r => r.acceptance === 'PASSABLE').slice(0, 2);
const unacceptableExamples = ragResults.filter(r => r.acceptance === 'UNACCEPTABLE').slice(0, 2);

// Format for prompt
const formatExample = (ex) => `[${ex.acceptance}] (similarity: ${(ex.similarity * 100).toFixed(0)}%)\n${ex.example_text.substring(0, 500)}...`;

const ragContext = {
  hasResults: ragResults.length > 0,
  totalFound: ragResults.length,
  acceptableExamples: acceptableExamples.map(formatExample),
  passableExamples: passableExamples.map(formatExample),
  unacceptableExamples: unacceptableExamples.map(formatExample),
  topSimilarity: ragResults[0]?.similarity || 0,
  topAcceptance: ragResults[0]?.acceptance || 'UNKNOWN'
};

return [{ json: { ...prevData, ragContext, ragResults } }];

