  // Primary keys
  clause_instance_id: data.clause_instance_id,
  clause_id: data.clause_id,
  document_id: data.document_id,
  run_id: data.run_id,
  sequence_number: 0,

  // Content
  heading: data.routerOutput.route,
  clause_text: data.clause_text,
  detected_family: data.routerOutput.route,
  confidence_score: data.routerOutput.confidence || 0,

  // Client-facing state
  client_state: data.decisorOutput.client_state,
  client_comment: sanitizerOut.client_comment,
  client_summary_line: sanitizerOut.client_summary_line,

  // Proposed changes
  proposed_changes: data.valuatorOutput.proposed_changes || [],

  // Escalation
  escalation_recommended: data.decisorOutput.escalation?.recommended || false,
  escalation_reason: data.decisorOutput.escalation?.reason || null,

  // RAG metadata
  _rag: {
    examples_found: data.ragContext?.totalFound || 0,
    top_similarity: data.ragContext?.topSimilarity || 0,
    top_acceptance: data.ragContext?.topAcceptance || 'NONE',
    decision_factor: data.valuatorOutput?.rag_decision_factor || ''
  },

  // Internal tracking
  _internal: {
    decision: data.decisorOutput.decision,
    paranoid_summary: data.paranoidOutput?.summary,
    risk_level: data.paranoidOutput?.risk_level,
    safety_pass: sanitizerOut.safety?.pass,
    adjusted_confidence: data.decisorOutput?.adjustedConfidence
  },

  completed_at: new Date().toISOString()
};

return [{ json: result }];
